const crypto = require('crypto');
const b = $input.first().json.body || {};
const a = b.answers || {};
const fail = (error) => [{ json: { ok: false, error } }];

const esc = (s) => "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/[\r\n\0]/g, ' ') + "'";
const orNull = (s) => (s === undefined || s === null || s === '' ? 'NULL' : esc(String(s).slice(0, 100)));
const map = (table, v) => (Object.prototype.hasOwnProperty.call(table, v) ? table[v] : null);
const enumOrNull = (v) => (v === null ? 'NULL' : esc(v));

const email = String(b.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) || email.length > 255) return fail('email_invalide');

const password = String(b.password || '');
if (password.length < 10 || !/[^A-Za-z0-9]/.test(password)) return fail('mot_de_passe_faible');

const gender = b.gender === 'homme' || b.gender === 'femme' ? b.gender : null;
if (!gender) return fail('genre_manquant');

const birthYear = parseInt(b.birth_year, 10);
const thisYear = new Date().getFullYear();
if (!(birthYear >= 1930 && birthYear <= thisYear - 18)) return fail('age_invalide');

if (b.consent !== true) return fail('consentement_manquant');

const T = {
  connaissance: { '1-2 mois': '1-2_mois', '3-4 mois': '3-4_mois', '4-12 mois': '4-12_mois', '1-2 ans': '1-2_ans' },
  delai: { '1-2 mois': '1-2_mois', '2-4 mois': '2-4_mois', '4-6 mois': '4-6_mois', 'À convenir ensemble': 'a_convenir' },
  badge: { 'Oui': 'oui', 'Non': 'non', 'Je déciderai plus tard': 'plus_tard' },
  croyance: { 'Islam — Sunnite': 'sunnite', 'Islam — Chiite': 'chiite', 'Islam — Soufi': 'soufi', 'Islam — Ahmadiyya': 'ahmadiyya', 'Islam — Autre': 'autre_islam', "En cours de réversion (conversion à l'Islam)": 'en_reversion', 'Je préfère ne pas répondre': 'ne_pas_repondre', 'Autre': 'autre' },
  pratique: { 'Très pratiquant(e)': 'tres_pratiquant', 'Pratiquant(e)': 'pratiquant', 'Peu pratiquant(e)': 'peu_pratiquant' },
  alcool: { 'Oui': 'oui', 'Occasionnellement': 'occasionnellement', 'Non': 'non', 'Je préfère ne pas répondre': 'ne_pas_repondre' },
  tabac: { 'Oui': 'oui', 'Non': 'non', 'Occasionnellement': 'occasionnellement' },
  enfants: { 'Oui': 'oui', 'Je ne sais pas encore': 'pas_sur', 'Non': 'non' },
  situation: { 'Célibataire': 'celibataire', 'Séparé(e)': 'separe', 'Divorcé(e)': 'divorce', 'Veuf / Veuve': 'veuf_veuve', 'Autre': 'autre', 'Je préfère ne pas répondre': 'ne_pas_repondre' },
  apparence: { 'En dessous de la moyenne': 'en_dessous_moyenne', 'Dans la moyenne': 'moyenne', 'Attirant(e)': 'attirant', 'Très attirant(e)': 'tres_attirant' },
  sante: { 'Non': 'non', 'Oui': 'oui', 'Je préfère en parler plus tard': 'plus_tard' },
  corpulence: { 'Menue': 'menue', 'Mince': 'mince', 'Sportive': 'sportive', 'Moyenne': 'moyenne', 'Quelques kilos en trop': 'quelques_kilos', 'Forte': 'forte', 'Grande et élégante': 'grande_elegante' },
  priorites: { 'Prière assidue (plusieurs fois par jour)': 'priere', 'Étude du Coran': 'etude_coran', 'Jeûne (Sunnah)': 'jeune', 'Sadaqah (aumône)': 'sadaqah', 'Umrah ou Hajj accompli(e)': 'umrah_hajj', "Apprentissage de l'arabe": 'arabe' }
};

const types = Array.isArray(a.type_relation) ? a.type_relation : [];
const relationship = types.includes('Mariage') ? 'mariage' : (types.length ? 'echange_serieux' : null);
const belief = map(T.croyance, a.croyance);
const marital = map(T.situation, a.situation_familiale);
if (!relationship || !belief || !marital) return fail('questionnaire_incomplet');

const ageMin = parseInt(a.age_recherche && a.age_recherche.min, 10);
const ageMax = parseInt(a.age_recherche && a.age_recherche.max, 10);
if (!(ageMin >= 18 && ageMax >= ageMin && ageMax <= 99)) return fail('tranche_age_invalide');

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha256').toString('hex');
const passwordHash = 'pbkdf2:100000:' + salt + ':' + hash;

const E = esc(email);
const idOf = '(SELECT id FROM members WHERE email=' + E + ')';
const loc = b.location || {};
const want = a.lieu_recherche || {};

const q0 = 'SELECT COUNT(*) AS n FROM members WHERE email=' + E;
const q1 = 'INSERT INTO members (email,password_hash,gender,consent_given_at) VALUES (' + E + ',' + esc(passwordHash) + ',' + esc(gender) + ',NOW())';
const q2 = 'INSERT INTO profiles (member_id,birth_year,country,region,city,relationship_type,knowing_timeframe,marriage_timeframe,nikah_badge,ethnicity,belief,religious_level,drinks,smokes,wants_children,marital_status,appearance,health_obstacle) VALUES (' + [
  idOf, birthYear, orNull(loc.pays), orNull(loc.region), orNull(loc.ville), esc(relationship),
  enumOrNull(map(T.connaissance, a.duree_connaissance)), enumOrNull(map(T.delai, a.delai_mariage)), enumOrNull(map(T.badge, a.badge_nikah)),
  orNull((a.origine || '').slice(0, 50)), esc(belief), enumOrNull(map(T.pratique, a.pratique)), enumOrNull(map(T.alcool, a.alcool)),
  enumOrNull(map(T.tabac, a.tabac)), enumOrNull(map(T.enfants, a.enfants)), esc(marital), enumOrNull(map(T.apparence, a.apparence)), enumOrNull(map(T.sante, a.sante))
].join(',') + ')';
const q3 = 'INSERT INTO search_preferences (member_id,age_min,age_max,country,region,city) VALUES (' + [idOf, ageMin, ageMax, orNull(want.pays), orNull(want.region), orNull(want.ville)].join(',') + ')';

const prios = (Array.isArray(a.priorites) ? a.priorites : []).map((p) => map(T.priorites, p)).filter(Boolean);
const q4 = prios.length ? 'INSERT INTO practice_priorities (member_id,priority) VALUES ' + prios.map((p) => '(' + idOf + ',' + esc(p) + ')').join(',') : 'SELECT 1';

return [{ json: { ok: true, q0, q1, q2, q3, q4 } }];
